<div class="admin-page-actions"><div><span class="admin-kicker">Operaciones</span><h2>Pedidos</h2><p>Controlá pedidos, cobros y entregas desde un solo lugar.</p></div></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Pedido</th><th>Pago</th><th>Acción</th></tr></thead><tbody><?php foreach($adminOrders as $o):?><tr><td><strong>#<?=e($o['id_pedido'])?></strong></td><td><?=e($o['cliente'])?></td><td><?=e((new DateTimeImmutable($o['fecha_pedido']))->format('d/m/Y H:i'))?></td><td><?=e(money($o['total']))?></td><td><span class="admin-status status-<?=e(strtolower($o['estado']))?>"><?=e($o['estado'])?></span></td><td><span class="admin-status status-<?=e(strtolower($o['pago_estado']??'pendiente'))?>"><?=e($o['pago_estado']??'SIN PAGO')?></span><small class="d-block"><?=e($o['metodo']??'')?></small></td><td><a class="admin-outline-action" href="<?=e(url('admin-order',['id'=>$o['id_pedido']]))?>">Ver detalle</a></td></tr><?php endforeach;?></tbody></table><?php if(!$adminOrders):?><p class="admin-empty">Todavía no hay pedidos.</p><?php endif;?></div></section>
